	i.market_price AS market_price,
	i.item_category AS item_category,
	i.distributor_id AS distributor_id,
	ira.attribute_id AS attribute_id,
	ira.attribute_value_id AS attribute_value_id,
	ia.attribute_name AS attribute_name,
