	iav.attribuattribute_valuete_name AS attribute_value_name
FROM items_rel_attributes ira
LEFT JOIN items i ON ira.item_id = i.item_id
LEFT JOIN items_attributes ia ON ira.attribute_id = ia.attribute_id
LEFT JOIN items_attribute_values iav ON ira.attribute_value_id = iav.attribute_value_id

